def isValidBST(root):
    def ok(n, lo, hi):
        if not n:
            return True
        if lo is not None and n.val <= lo:
            return False
        if hi is not None and n.val >= hi:
            return False
        return ok(n.left, lo, n.val) and ok(n.right, n.val, hi)
    return ok(root, None, None)

