def isValidBST(root):
    vals, st, cur = [], [], root
    while st or cur:
        while cur:
            st.append(cur)
            cur = cur.left
        cur = st.pop()
        vals.append(cur.val)
        cur = cur.right
    return all(vals[i] < vals[i + 1] for i in range(len(vals) - 1))

